import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse('{"title":"UXS-006 — Moon Map","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/UXS-006.md","filePath":"uxs/UXS-006.md"}'),s={name:"uxs/UXS-006.md"};function i(r,e,l,d,h,c){return t(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="uxs-006-—-moon-map" tabindex="-1">UXS-006 — Moon Map <a class="header-anchor" href="#uxs-006-—-moon-map" aria-label="Permalink to &quot;UXS-006 — Moon Map&quot;">​</a></h1><blockquote><p>Status · Draft v0.1 Visual fidelity · Verified against prototype (P06_moon-map.html) IA anchor · §surfaces/moon · §topbar-patterns · §shared-tokens Related PRD · PRD-006</p></blockquote><h2 id="why-this-uxs-exists" tabindex="-1">Why this UXS exists <a class="header-anchor" href="#why-this-uxs-exists" aria-label="Permalink to &quot;Why this UXS exists&quot;">​</a></h2><p>The Moon Map has two views (3D sphere and 2D flat map) and a detail panel pattern specific to landing sites. This UXS defines both views, the landing site marker appearance, the nation colour system, and the site detail panel.</p><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><ul><li>The 3D sphere rotation is the primary discovery mechanism — rotating to find the far side teaches something</li><li>Landing site markers are visible but not cluttered</li><li>Nation colour distinguishes 5 nations without a legend once learned</li><li>&quot;Still on the surface&quot; callout is the most emotionally impactful element of each panel — it must be prominent</li></ul><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>In scope: nav bar, 3D sphere view, 2D flat map view, 3D/2D toggle, landing site markers, detail panel (OVERVIEW, GALLERY tabs), nation colour system. Non-goals: sphere texture detail level, map projection choice. Boundary note: sphere rotation physics belongs in the screen module.</p><h2 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to &quot;Theme&quot;">​</a></h2><p>Dark only.</p><h2 id="tokens" tabindex="-1">Tokens <a class="header-anchor" href="#tokens" aria-label="Permalink to &quot;Tokens&quot;">​</a></h2><h3 id="inherited-from-ia" tabindex="-1">Inherited from IA <a class="header-anchor" href="#inherited-from-ia" aria-label="Permalink to &quot;Inherited from IA&quot;">​</a></h3><p>All shared tokens.</p><h3 id="defined-here" tabindex="-1">Defined here <a class="header-anchor" href="#defined-here" aria-label="Permalink to &quot;Defined here&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nation-usa:     #4b9cd3   US sites</span></span>
<span class="line"><span>nation-ussr:    #c07070   Soviet sites</span></span>
<span class="line"><span>nation-china:   #c1440e   Chinese sites</span></span>
<span class="line"><span>nation-india:   #ff9933   Indian sites</span></span>
<span class="line"><span>nation-japan:   #ffffff   Japanese sites</span></span>
<span class="line"><span></span></span>
<span class="line"><span>site-marker-size:  4–6px radius depending on mission significance</span></span>
<span class="line"><span>site-marker-glow:  nation colour, 3× radius</span></span>
<span class="line"><span>site-selected:     nation colour, pulsing ring</span></span>
<span class="line"><span>moon-surface:      Three.js texture from static/textures/moon_1024.jpg</span></span></code></pre></div><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><h3 id="_3d-view" tabindex="-1">3D view <a class="header-anchor" href="#_3d-view" aria-label="Permalink to &quot;3D view&quot;">​</a></h3><p>Full-viewport Three.js sphere. Nav bar overlaid. 3D/2D toggle top-right. Landing site markers as Three.js sprites or projected HTML divs. Detail panel right 400px on site click.</p><h3 id="_2d-flat-map" tabindex="-1">2D flat map <a class="header-anchor" href="#_2d-flat-map" aria-label="Permalink to &quot;2D flat map&quot;">​</a></h3><p>Full-viewport Canvas 2D. Equirectangular projection. Site markers as circles at lat/lon-mapped coordinates. Nation legend bottom-left. Detail panel same as 3D.</p><h3 id="site-detail-panel" tabindex="-1">Site detail panel <a class="header-anchor" href="#site-detail-panel" aria-label="Permalink to &quot;Site detail panel&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────────┐</span></span>
<span class="line"><span>│  NATION FLAG/COLOUR · AGENCY      │</span></span>
<span class="line"><span>│  MISSION NAME (Bebas Neue 32px)   │</span></span>
<span class="line"><span>│  Year · Type · Status             │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│  OVERVIEW │ GALLERY               │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│  [Still on the surface]           │</span></span>
<span class="line"><span>│  nation-colour left border        │</span></span>
<span class="line"><span>│  &quot;Hardware still on the Moon:&quot;    │</span></span>
<span class="line"><span>│  - Descent stage                  │</span></span>
<span class="line"><span>│  - Rover (if applicable)          │</span></span>
<span class="line"><span>├───────────────────────────────────┤</span></span>
<span class="line"><span>│  Editorial description            │</span></span>
<span class="line"><span>│  (Space Mono upright, 15px)         │</span></span>
<span class="line"><span>│                                   │</span></span>
<span class="line"><span>│  Capability proved:               │</span></span>
<span class="line"><span>│  First [X] — required for Mars    │</span></span>
<span class="line"><span>└───────────────────────────────────┘</span></span></code></pre></div><h2 id="site-index" tabindex="-1">Site index <a class="header-anchor" href="#site-index" aria-label="Permalink to &quot;Site index&quot;">​</a></h2><p>The left-edge INDEX (<code>SurfaceIndexPanel</code>, <a href="./decisions/UXD-017-one-index-on-every-scale">UXD-017</a> amendment, C6) leads each site&#39;s row with the round photo of the image its panel shows (L45-T2, <a href="./decisions/UXD-025-lists-carry-a-round-photo">UXD-025</a>: <code>/moon</code> 28 of 28, <code>/mars</code> 27 of 27, <code>/venus</code> 3 of 3), ringed in the nation&#39;s colour, the colour of the nation legend swatch; a site with no photo draws that colour as a dot with a 1px light ring so the dark hues read; the meta line is <code>year · status · In orbit</code> or <code>· On land</code>, the words of the Orbit and Land chips. The agency, era and status chips are folded behind a FILTERS button beside the count (labelled groups, closed at the start, the button carries the number of filters on; C6-F, <a href="./decisions/UXD-017-one-index-on-every-scale">UXD-017</a> amendment), so the panel is the search, one row of chips, the count and the list. /mars, /venus and /earth&#39;s launch sites follow the same rule.</p><h2 id="welcome-hint" tabindex="-1">Welcome hint <a class="header-anchor" href="#welcome-hint" aria-label="Permalink to &quot;Welcome hint&quot;">​</a></h2><p>One dismissible line near the bottom centre (under the top row on touch): &quot;Zoom in to explore · drag to look around&quot; (<code>ExploreHint</code>, <code>surface_hint_zoom</code>, <a href="./decisions/UXD-027-explore-levels-one-table-glyphs-card-and-hint">UXD-027</a>). It is the same component as /explore&#39;s, mounted once in <code>SurfaceScene</code> for /earth, /moon, /mars and /venus: gone at the first wheel turn, pinch, tap or drag on the canvas, at its ×, or after 12 s, and shown again on the next visit. Showing a few site markers at the start zoom is not part of it.</p><h2 id="orbit-ruler-and-bottom-left-column" tabindex="-1">Orbit ruler and bottom-left column <a class="header-anchor" href="#orbit-ruler-and-bottom-left-column" aria-label="Permalink to &quot;Orbit ruler and bottom-left column&quot;">​</a></h2><p>On /moon and /mars the orbit ruler follows <a href="./UXS-014#the-orbit-ruler">UXS-014</a> (<a href="./decisions/UXD-024-orbit-ruler-one-row-draws-its-regime">UXD-024</a>). /moon&#39;s lower-left corner is one column: the &quot;AS SEEN FROM YOU&quot; readout, the locate chip, the ruler; the Moon/Mars imagery card stays outside it and rises above it. /mars has the ruler alone.</p><h2 id="selected-orbiter" tabindex="-1">Selected orbiter <a class="header-anchor" href="#selected-orbiter" aria-label="Permalink to &quot;Selected orbiter&quot;">​</a></h2><p>An orbiter site selected in the 3D view (LRO and Lunar Prospector on /moon, MRO on /mars) keeps the orbits in view: its dot, its ring, the other orbiters and the ruler stay drawn while it is selected, although the fly-in lands under one body radius (<code>orbitsInViewNext</code>, <code>surface-view-state.ts</code>); the selected orbiter wears the outline pass, as on hover. With the site panel open the 3D view shifts so every selection, a surface site or an orbiter, sits in the middle of the space the panel leaves (half the panel&#39;s width, 200 px for the 400 px drawer; a touch-portrait sheet shifts nothing; not in the 2D map, the flat ground patch or a panorama). Closing an orbiter&#39;s panel clears the selection, and the orbits hide again when the camera is under one radius (<a href="./decisions/UXD-030-worlds-selected-orbiter-stays-visible-and-framed">UXD-030</a>).</p><h2 id="rover-and-eva-routes-uxd-044" tabindex="-1">Rover and EVA routes (<a href="./decisions/UXD-044-moon-traverses-take-the-mars-line-style">UXD-044</a>) <a class="header-anchor" href="#rover-and-eva-routes-uxd-044" aria-label="Permalink to &quot;Rover and EVA routes ([UXD-044](decisions/UXD-044-moon-traverses-take-the-mars-line-style.md))&quot;">​</a></h2><p>A Moon route is drawn in the style the Mars routes use (Design System §5.22): the dark casing, the 4 px line coloured blue to white to amber, here <strong>by the distance driven</strong> (the Moon files carry no time), kilometre milestone pills, the green landing ring on the path, the stop rings and &quot;name&quot; pills (a Moon stop has no sol, so its pill is the name only), and the path hover card, &quot;N km from landing&quot;. The nation colour stays on the site marker, the INDEX dot and the panel. Sol ticks, the replay marker, photo pins and the JOURNEY tab are Mars-only: they need a time or a photo the Moon files do not have. Chang&#39;e 3 (Yutu) and Chandrayaan-3 (Pragyan) are 9-point outlines, not surveyed tracks; their panel says &quot;Approximate route&quot; (OVERVIEW tab, above the credit). Eight routes: Lunokhod 1 and 2, Yutu-2 and Apollo 15, 16, 17 (LROC / USGS mapped), Yutu and Pragyan (approximate).</p><h2 id="back-to-explore" tabindex="-1">Back to Explore <a class="header-anchor" href="#back-to-explore" aria-label="Permalink to &quot;Back to Explore&quot;">​</a></h2><p>The first control of the view row is &quot;Back to Explore&quot; (the first chip of <code>hud-top-mobile</code> on touch): on /moon a link to <code>/explore?id=earth:moon</code>, on /mars to <code>/explore?id=mars</code>, on /venus to <code>/explore?id=venus</code>, where the body&#39;s panel opens and the camera is on it (<a href="./decisions/UXD-028-explore-and-worlds-link-both-ways">UXD-028</a>, D5: an explicit link both ways, never a switch on zoom). The Explore panels of the four bodies carry the matching &quot;Go to Mars&quot; (and so on) chip (Venus included). The chip hides with the rest of the row while a panorama is open or the flat ground patch is up; the nav&#39;s EXPLORE group stays.</p><h2 id="component-states" tabindex="-1">Component states <a class="header-anchor" href="#component-states" aria-label="Permalink to &quot;Component states&quot;">​</a></h2><p><strong>Site marker (default):</strong> small circle, nation colour <strong>Site marker (hovered):</strong> slightly larger, brighter glow <strong>Site marker (selected):</strong> pulsing ring, panel open <strong>&quot;Still on the surface&quot; block:</strong> nation-colour left border, <code>rgba(nation,0.08)</code> background <strong>3D/2D toggle:</strong> same pattern as explore screen (vtab style)</p><h2 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h2><p>Canvas/WebGL: <code>aria-label=&quot;Interactive Moon map with 16 landing sites. Use the detail panels for screen reader access.&quot;</code>. Detail panels are HTML — screen reader accessible.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><blockquote><p><strong>As-built note (2026-10-16):</strong> the boxes below were not maintained after implementation and are not a record of what shipped. For shipped behaviour see <a href="./../adr/TA"><code>docs/adr/TA.md</code></a> and <a href="./../../CHANGELOG"><code>CHANGELOG.md</code></a>.</p></blockquote><ul><li>[ ] All 16 landing sites visible in both 3D and 2D views</li><li>[ ] Far-side sites (Chang&#39;e 4) only visible when sphere is rotated</li><li>[ ] Each site colour-coded by nation</li><li>[ ] Detail panel opens on site click</li><li>[ ] &quot;Still on the surface&quot; block present for all missions that left hardware</li><li>[ ] Capability callout present in each panel</li><li>[ ] 3D/2D toggle switches views without losing selected site</li><li>[ ] 2D flat map shows all 16 sites at approximately correct lat/lon positions</li></ul><hr><h2 id="extension-—-gallery-learn-tabs-v0-1-10" tabindex="-1">Extension — GALLERY + LEARN tabs (v0.1.10) <a class="header-anchor" href="#extension-—-gallery-learn-tabs-v0-1-10" aria-label="Permalink to &quot;Extension — GALLERY + LEARN tabs (v0.1.10)&quot;">​</a></h2><p>The detail panel gains a tab system: OVERVIEW (existing content) · GALLERY · LEARN. CSS sourced from the shared <code>src/lib/styles/panel-tabs.css</code> introduced in v0.1.10.</p><h3 id="layout-1" tabindex="-1">Layout <a class="header-anchor" href="#layout-1" aria-label="Permalink to &quot;Layout&quot;">​</a></h3><ul><li>Tabs row sits below the agency-row + name + mission-type header, above the existing landing-data grid.</li><li>GALLERY tab renders only when <code>static/data/moon-site-galleries.json[id] &gt; 0</code>. For sites that share an ID with a flown mission (Apollo 11, Chang&#39;e 5, Luna 9, etc.) the photos are copied from <code>images/missions/&lt;id&gt;/</code> at build time — same content, different surface.</li><li>LEARN tab renders only when the moon-site record has non-empty <code>links[]</code>.</li><li>STORY (a lander&#39;s story, landing sheet and &quot;On the surface&quot; drawing) and DETAIL (an orbiter&#39;s drawing under &quot;The spacecraft&quot;, <code>panel_tab_detail</code>) are the two craft tabs: an orbiter site (<code>kind: &#39;orbiter&#39;</code>) has DETAIL, never STORY or &quot;On the surface&quot;; 17 of the 19 Moon and Mars orbiters have a drawing and so the tab (<a href="./decisions/UXD-034-worlds-orbiter-detail-tab-and-panorama-opening">UXD-034</a>).</li><li>Order: header, action row, hero (the first gallery image), tabs, body, for every site and orbiter; the photograph comes first.</li><li>One gallery ladder for Moon, Mars and Venus (<code>getSurfaceSiteGallery</code>, <a href="./decisions/UXD-036-venus-galleries-use-the-worlds-ladder">UXD-036</a>): the three Venus sites have a hero (the blessed mission slot) and a GALLERY tab with the credit line like the others (<code>venus-sites.spec.ts</code>).</li><li>&quot;Stand here&quot; opens on the photograph: <code>entry_yaw_deg</code> (0 when absent) lies inside <code>panorama_metadata.photo_span_deg</code> and clear of its edge; a <code>?yaw=</code> deep link wins (<a href="./decisions/UXD-007-panorama-opens-facing-the-photo">UXD-007</a>).</li></ul><h3 id="tokens-extension" tabindex="-1">Tokens (extension) <a class="header-anchor" href="#tokens-extension" aria-label="Permalink to &quot;Tokens (extension)&quot;">​</a></h3><p>Inherits all panel-tab tokens from UXS-004 §Extension. Active tab border: <code>#5070ff</code>. GALLERY thumb hover: <code>rgba(80, 112, 255, 0.6)</code>. LEARN tiers: muted blue <code>#889fe7</code> (intro) · blue (core) · gold (deep).</p><h3 id="acceptance-criteria-extension" tabindex="-1">Acceptance criteria (extension) <a class="header-anchor" href="#acceptance-criteria-extension" aria-label="Permalink to &quot;Acceptance criteria (extension)&quot;">​</a></h3><ul><li>[ ] OVERVIEW tab content (data grid + &quot;still on the surface&quot; block + capability callout + fact + credit) unchanged</li><li>[ ] GALLERY tab renders Apollo 11 photos identical to those on /missions for the same mission (no duplicate downloads)</li><li>[ ] LEARN tab renders tiered links from <code>moon-site.links</code></li><li>[ ] No GALLERY/LEARN tab on sites without data</li><li>[ ] An orbiter with a drawing has DETAIL (&quot;The spacecraft&quot;) and no STORY; a lander keeps STORY (<code>surface-orbiter-details.spec.ts</code>)</li><li>[ ] Hero before the tab row on every Moon, Mars and Venus site with a gallery (<code>surface-panel-order.spec.ts</code>)</li><li>[ ] &quot;Stand here&quot; opens inside the photograph on each of the 18 partial panoramas (<code>panorama-entry.spec.ts</code>, <code>panorama-entry.data.test.ts</code>)</li></ul>`,50)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
